// StageLyrics service worker: caches the app shell so the app works offline at the venue.
// VERSION and ASSETS are generated by `npm run sw:stamp` (tools/stamp-sw.mjs). Don't edit them by hand.
// A new version installs in the background and waits; it only takes over when the page posts SKIP_WAITING
// (the "Update ready — Reload" banner), so a performance is never interrupted.

const VERSION = '67af141b'
const ASSETS = [
  './',
  'index.html',
  'manifest.webmanifest',
  'css/app.css',
  'js/clock.js',
  'js/demo.js',
  'js/format.js',
  'js/lrc.js',
  'js/paste.js',
  'js/platform.js',
  'js/router.js',
  'js/song.js',
  'js/timing.js',
  'js/ui/dom.js',
  'icons/apple-touch-icon.png',
  'icons/icon-192.png',
  'icons/icon-512.png',
  'icons/icon-maskable-512.png',
  'icons/icon.svg',
]

const PREFIX = 'stagelyrics-'
const CACHE = PREFIX + VERSION

const scopeUrl = (path) => new URL(path, self.registration.scope).href

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE).then((cache) =>
      cache.addAll(ASSETS.map((u) => new Request(new URL(u, self.registration.scope), { cache: 'reload' }))),
    ),
  )
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith(PREFIX) && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  )
})

self.addEventListener('fetch', (event) => {
  const req = event.request
  if (req.method !== 'GET' || !req.url.startsWith(self.registration.scope)) return
  event.respondWith(req.mode === 'navigate' ? shell(req) : cacheFirst(req))
})

self.addEventListener('message', (event) => {
  if (event.data?.type === 'SKIP_WAITING') self.skipWaiting()
})

// Only this version's cache is consulted: a waiting worker's newer files must never leak into the running page.
async function fromCache(req, opts) {
  try {
    const cache = await caches.open(CACHE)
    return await cache.match(req, opts)
  } catch {
    return undefined
  }
}

async function shell(req) {
  return (await fromCache(scopeUrl('index.html'))) ?? fetch(req)
}

async function cacheFirst(req) {
  return (await fromCache(req, { ignoreSearch: true })) ?? fetch(req)
}
